from __future__ import absolute_import

from .common_page import CommonPage
from .panels.view import ViewPanel


class UserAccountManagement(CommonPage):
    """
    The class corresponding to User Account Management page on selenium_coam web, all operations under User Account
    Management page will be implemented or added in its corresponding classes.
    """
    _instance_dict = {}

    def __init__(self, driver, version):
        if not self._instance_dict:
            self._instance_dict = {"Local User Account Management": LocalUserAccountManagementTab(driver, version),
                                   "Service User Account Management": ServiceUserAccountManagementTab(driver, version)}
        super(UserAccountManagement, self).__init__(driver, version, self._instance_dict)


class AccountManagementCommon(ViewPanel):
    def __init__(self, driver, version):
        super(AccountManagementCommon, self).__init__(driver, version)

    def submit_and_get_success_message(self, change_action=None, account_type="local", deactivate=False):
        if self.element_exists(self.locator.CONFIRM_PASSWORD_ERROR_MESSAGE):
            return "Confirm password must be identical with the new password"
        if self.check_validation_rules() and not deactivate:
            return "Given {} failed to meet validation rules".format(change_action)
        self.click_enabled_element(self.locator.SUBMIT_BUTTON)
        if account_type == "Service":
            self.wait_for_visibility(self.locator.SERVICE_USER_SUCCESS_MESSAGE)
        else:
            self.wait_for_visibility(self.locator.LOCAL_USER_SUCCESS_MESSAGE)
        return self.get_text(self.locator.ALERT_MESSAGE)

    def select_element_from_drop_down(self, drop_down, option):
        if drop_down == 'user_update':
            self.click_enabled_element(self.locator.LOCAL_USER_UPDATE_DROP_DOWN)
        else:
            self.click_enabled_element(self.locator.ACTIVE_STATE_DROP_DOWN)
        self.click_enabled_element(self.locator.SELECT_FROM_LOCAL_USER_UPDATE_DROP_DOWN.format(option))

    def check_validation_rules(self):
        if self.element_exists("//div[@data-validation-rule-is-passed='false']", timeout=3):
            return True
        return False


class LocalUserAccountManagementTab(AccountManagementCommon):
    """
    As a class will be called by User Account Management, all operations under Local user will be implemented under
    this class.
    """
    MENU_ROUTE_LIST = ['account', 'Local Users']

    def __init__(self, driver, version):
        super(LocalUserAccountManagementTab, self).__init__(driver, version)

    def change_local_users_password(self, current_password, new_password, confirm_new_password):
        if confirm_new_password is None:
            confirm_new_password = new_password
        self.select_element_from_drop_down('user_update', 'Password')
        self.insert_text_to_enable_element(self.locator.CURRENT_PASSWORD_INPUT, current_password)
        self.insert_text_to_enable_element(self.locator.NEW_PASSWORD_INPUT, new_password)
        self.insert_text_to_enable_element(self.locator.CONFIRM_PASSWORD_INPUT, confirm_new_password)
        return self.submit_and_get_success_message("Password")

    def change_local_users_user_name(self, new_user_name, current_password):
        self.select_element_from_drop_down('user_update', 'Username')
        self.insert_text_to_enable_element(self.locator.USER_NAME_INPUT, new_user_name)
        self.insert_text_to_enable_element(self.locator.CURRENT_PASSWORD_INPUT, current_password)
        return self.submit_and_get_success_message("User Name")

    def change_local_users_user_name_and_password(self, new_user_name, current_password, new_password,
                                                  confirm_new_password):
        if confirm_new_password is None:
            confirm_new_password = new_password
        self.select_element_from_drop_down('user_update', 'Password and Username')
        self.insert_text_to_enable_element(self.locator.USER_NAME_INPUT, new_user_name)
        self.insert_text_to_enable_element(self.locator.CURRENT_PASSWORD_INPUT, current_password)
        self.insert_text_to_enable_element(self.locator.NEW_PASSWORD_INPUT, new_password)
        self.insert_text_to_enable_element(self.locator.CONFIRM_PASSWORD_INPUT, confirm_new_password)
        return self.submit_and_get_success_message("User Name and Password")

    def activate_bts_application_administrator(self, password):
        self.select_element_from_drop_down('user_update', 'BTS Application Administrator')
        self.select_element_from_drop_down('activation_status', 'active')
        self.insert_text_to_enable_element(self.locator.NEW_PASSWORD_INPUT, password)
        self.insert_text_to_enable_element(self.locator.CONFIRM_PASSWORD_INPUT, password)
        return self.submit_and_get_success_message()

    def activate_bts_read_only_user(self, password):
        self.select_element_from_drop_down('user_update', 'BTS Read-Only User')
        self.select_element_from_drop_down('activation_status', 'active')
        self.insert_text_to_enable_element(self.locator.NEW_PASSWORD_INPUT, password)
        self.insert_text_to_enable_element(self.locator.CONFIRM_PASSWORD_INPUT, password)
        return self.submit_and_get_success_message()

    def activate_bts_security_administrator(self, password):
        self.select_element_from_drop_down('user_update', 'BTS Security Administrator')
        self.select_element_from_drop_down('activation_status', 'active')
        self.insert_text_to_enable_element(self.locator.NEW_PASSWORD_INPUT, password)
        self.insert_text_to_enable_element(self.locator.CONFIRM_PASSWORD_INPUT, password)
        return self.submit_and_get_success_message()

    def deactivate_bts_application_administrator(self):
        self.select_element_from_drop_down('user_update', 'BTS Application Administrator')
        self.select_element_from_drop_down('activation_status', 'deactive')
        return self.submit_and_get_success_message(deactivate=True)

    def deactivate_bts_read_only_user(self):
        self.select_element_from_drop_down('user_update', 'BTS Read-Only User')
        self.select_element_from_drop_down('activation_status', 'deactive')
        return self.submit_and_get_success_message(deactivate=True)

    def deactivate_bts_security_administrator(self):
        self.select_element_from_drop_down('user_update', 'BTS Security Administrator')
        self.select_element_from_drop_down('activation_status', 'deactive')
        return self.submit_and_get_success_message(deactivate=True)


class ServiceUserAccountManagementTab(AccountManagementCommon):
    """
    As a class will be called by User Account Management, all operations under Service user will be implemented under
    this class.
    """
    MENU_ROUTE_LIST = ['account', 'Service Users']

    def __init__(self, driver, version):
        super(ServiceUserAccountManagementTab, self).__init__(driver, version)

    def change_service_users_password(self, service_user_name, current_service_password, new_service_password):
        self.insert_text_to_enable_element(self.locator.USER_NAME_INPUT, service_user_name)
        self.insert_text_to_enable_element(self.locator.CURRENT_PASSWORD_INPUT, current_service_password)
        self.insert_text_to_enable_element(self.locator.NEW_PASSWORD_INPUT, new_service_password)
        self.insert_text_to_enable_element(self.locator.CONFIRM_PASSWORD_INPUT, new_service_password)
        return self.submit_and_get_success_message("Password", "Service")
